        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, round(approx_quantile(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name LIKE '%left_tickets%' GROUP BY ALL", "claim": "Seat's left_tickets server span p95 rises to about 131s in the abnormal period."},
